    ('university', 'عمادة التعليم عن بعد بجامعة طيبة', 'Deanship of Distance Learning on the University of Thebes', 24.483954::double precision, 39.570455::double precision, 'OpenStreetMap © contributors (ODbL) osm:node/4534660562'),
    ('university', 'كلية العلوم وهندسة الحاسب الآلي', 'College of Computer Science and Engineering', 24.41231::double precision, 39.52665::double precision, 'OpenStreetMap © contributors (ODbL) osm:relation/21141166'),
    ('university', 'كلية الغد الدولية للعلوم الطبية التطبيقية', 'كلية الغد الدولية للعلوم الطبية التطبيقية', 24.446976::double precision, 39.619724::double precision, 'OpenStreetMap © contributors (ODbL) osm:node/8026336436')
  ) as s(kind, name_ar, name_en, lat, lng, source)
 where not exists (
     select 1 from destination_landmarks l
      where l.city_id = c.id and l.kind = s.kind
